const m = code.match(/<a\s[^>]*href=["']([^"']*)["']/i);
if (!m || m[1] !== "https://developer.mozilla.org") {
  throw new Error("The href must be exactly https://developer.mozilla.org — the protocol was missing.");
}

const m = code.match(/<a\s[^>]*href=[^>]*>([\s\S]*?)<\/a>/i);
if (!m || m[1].trim() !== "MDN Web Docs") {
  throw new Error("The link text must read: MDN Web Docs");
}

if (!/the <a\s[\s\S]*?<\/a> has the answers/i.test(code)) {
  throw new Error("Keep the surrounding sentence — only fix the link element itself.");
}
